const SCENE_NAME = 'keo-ngot'
const COMMAND = 'giao-dien-keo-ngot'

const { theme, problems } = makeColors({"label":"Kẹo ngọt","roles":{"accent":"#E2589A","danger":"#C0392B","success":"#2E8B57","warning":"#C27A1A","pro":"#8E5BD6"},"light":{"gray":{"anchors":{"surface-0":"#f0e5eb","surface-1":"#f7f0f4","surface-2":"#fcfafb","text-primary":"#2e1421","text-secondary":"#5b3347","text-muted":"#744e61"}}},"dark":{"gray":{"anchors":{"surface-0":"#170c12","surface-1":"#201118","surface-2":"#28151f","surface-3":"#321a26","text-primary":"#f2e9ed","text-secondary":"#d5c3cc","text-muted":"#b79fab"}}}})

