const LOOK: ThemeSetArgs = {
  colors: theme,
  backdrop: { scene: SCENE_NAME, glass: {"blur":3,"opacity":0.3} },
}

// 'on' while this look was the last one set, 'off' once another look took over.
const STORE_KEY = 'look'

